package com.ecole.gestion_scolaire.registration.service; import com.ecole.gestion_scolaire.registration.dto.*; import com.ecole.gestion_scolaire.registration.entity.StudentRegistrationInfo; import com.ecole.gestion_scolaire.registration.repository.StudentRegistrationInfoRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class RegistrationInfoService {private final StudentRegistrationInfoRepository repo;private final RegistrationCaseService cases;public RegistrationInfoService(StudentRegistrationInfoRepository r,RegistrationCaseService c){repo=r;cases=c;} public RegistrationInfoResponse find(Long id){return repo.findByRegistrationCaseId(id).map(this::map).orElse(null);}@Transactional public RegistrationInfoResponse save(Long id,RegistrationInfoRequest r){var x=repo.findByRegistrationCaseId(id).orElseGet(()->{var n=new StudentRegistrationInfo();n.setRegistrationCase(cases.get(id));return n;});x.setPreviousSchool(trim(r.previousSchool()));x.setPreviousClass(trim(r.previousClass()));x.setNotes(trim(r.notes()));return map(repo.save(x));}private RegistrationInfoResponse map(StudentRegistrationInfo x){return new RegistrationInfoResponse(x.getId(),x.getRegistrationCase().getId(),x.getPreviousSchool(),x.getPreviousClass(),x.getNotes());}private String trim(String s){return s==null?null:s.trim();}}
